from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test-order-1")
async def test_order_1(form_data: str = Form(...), file_data: bytes = File(...)):
    return {"form_data": form_data, "file_data": file_data}

@app.post("/test-order-2")
async def test_order_2(file_data: bytes = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file_data": file_data}

client = TestClient(app)

def test_order_1():
    # Form then File
    response = client.post(
        "/test-order-1",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    print(f"Order 1 response: {response.status_code}, {response.json()}")
    assert response.status_code == 200

def test_order_2():
    # File then Form
    response = client.post(
        "/test-order-2",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    print(f"Order 2 response: {response.status_code}, {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_order_1()
        print("test_order_1 passed")
    except Exception as e:
        print(f"test_order_1 failed: {e}")

    try:
        test_order_2()
        print("test_order_2 passed")
    except Exception as e:
        print(f"test_order_2 failed: {e}")

