import asyncio
from fastapi import FastAPI, File, Form
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test")
async def test_endpoint(
    form_data: str = Form(...),
    file_data: bytes = File(...)
):
    return {"form_data": form_data, "file_data_len": len(file_data)}

client = TestClient(app)

def test_form_then_file():
    # This should have failed with 422 before the fix
    response = client.post(
        "/test",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_data_len": 5}

def test_file_then_form():
    # This should have always passed
    response = client.post(
        "/test",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_data_len": 5}

if __name__ == "__main__":
    try:
        test_form_then_file()
        test_file_then_form()
        print("Tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        exit(1)
